<?php
require_once __DIR__.'/../../includes/auth.php'; requireHOD(); $p=db();$d=$_SESSION['user']['department_id'];
$q=$p->prepare('SELECT * FROM batches WHERE department_id=? ORDER BY batch_name');$q->execute([$d]);$batches=$q->fetchAll();$bid=(int)($_REQUEST['batch_id']??($batches[0]['id']??0));$sem=(int)($_REQUEST['semester_id']??1);$semesters=$p->query('SELECT * FROM semesters ORDER BY semester_number')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$subject=(int)$_POST['subject_id'];$lecturer=(int)$_POST['lecturer_id'];$check=$p->prepare('SELECT s.id FROM subjects s JOIN users u ON u.id=? JOIN batches b ON b.id=? WHERE s.id=? AND s.department_id=? AND s.semester_id=? AND u.department_id=? AND u.role="lecturer" AND b.department_id=?');$check->execute([$lecturer,$bid,$subject,$d,$sem,$d,$d]);if(!$check->fetch()){flash('Invalid subject or lecturer.','error');}else{try{$exists=$p->prepare('SELECT id FROM batch_subjects WHERE batch_id=? AND subject_id=?');$exists->execute([$bid,$subject]);if($id=$exists->fetchColumn())$p->prepare('UPDATE batch_subjects SET lecturer_id=?,semester_id=? WHERE id=?')->execute([$lecturer,$sem,$id]);else $p->prepare('INSERT INTO batch_subjects(batch_id,semester_id,subject_id,lecturer_id) VALUES(?,?,?,?)')->execute([$bid,$sem,$subject,$lecturer]);flash('Lecturer assignment saved.');}catch(PDOException $e){flash('Unable to save the assignment.','error');}}redirect('/hod/batches/manage.php?batch_id='.$bid.'&semester_id='.$sem);}
$q=$p->prepare("SELECT s.id,s.subject_code,s.subject_name,bs.id assignment_id,bs.lecturer_id FROM subjects s LEFT JOIN batch_subjects bs ON bs.subject_id=s.id AND bs.batch_id=? WHERE s.department_id=? AND s.semester_id=? AND s.status='active' ORDER BY s.subject_code");$q->execute([$bid,$d,$sem]);$subjects=$q->fetchAll();$q=$p->prepare("SELECT * FROM users WHERE department_id=? AND role='lecturer' AND status='active' ORDER BY name");$q->execute([$d]);$lecturers=$q->fetchAll();$title='Batch Lecturer Assignment';require __DIR__.'/../../includes/header.php';?>
<section class="panel"><form method="get" class="inline-form"><label>Batch<select name="batch_id" onchange="this.form.submit()"><?php foreach($batches as $b):?><option value="<?=$b['id']?>" <?=$bid===$b['id']?'selected':''?>><?=e($b['batch_name'])?></option><?php endforeach?></select></label><label>Semester<select name="semester_id" onchange="this.form.submit()"><?php foreach($semesters as $s):?><option value="<?=$s['id']?>" <?=$sem===$s['id']?'selected':''?>><?=e($s['semester_name'])?></option><?php endforeach?></select></label></form></section>
<section class="panel"><h2>Assign lecturers</h2><p>Subjects are managed under their semester in Subject Management.</p><div class="table-wrap"><table><tr><th>Code</th><th>Subject</th><th>Lecturer assignment</th><th></th></tr><?php foreach($subjects as $s):?><tr><td><?=e($s['subject_code'])?></td><td><?=e($s['subject_name'])?></td><td colspan="2"><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="batch_id" value="<?=$bid?>"><input type="hidden" name="semester_id" value="<?=$sem?>"><input type="hidden" name="subject_id" value="<?=$s['id']?>"><select name="lecturer_id" required><option value="">Select lecturer</option><?php foreach($lecturers as $u):?><option value="<?=$u['id']?>" <?=$s['lecturer_id']==$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach?></select><button>Save</button></form></td></tr><?php endforeach?></table></div></section><?php require __DIR__.'/../../includes/footer.php';?>
